window.RTLBenchLSData.register("assets/d3bd10c44d78c603d0d0c39602229d56410a21dfbb6fa2a4716ee99292dba599.txt","\n\n`timescale 1 ns/1 ps\n\nmodule SubBytes\n#\n(\n parameter DATA_W = 128,       \n parameter NO_BYTES = DATA_W >> 3  \n)\n(\ninput clk,                     \ninput reset,                   \ninput valid_in,                \ninput [DATA_W-1:0] data_in,    \noutput reg valid_out,          \noutput [DATA_W-1:0] data_out   \n)\n;\n\ngenvar i;\ngenerate                      \nfor (i=0; i< NO_BYTES ; i=i+1) begin : ROM\n  SBox ROM(clk,reset,valid_in,data_in[(i*8)+7:(i*8)],data_out[(i*8)+7:(i*8)]);   \nend\nendgenerate\n\nalways@(posedge clk or negedge reset)   \nif(!reset)begin\n    valid_out <= 1'b0;\nend else begin \n    valid_out <= valid_in;\n  end\nendmodule\n\n\n\n\n");
